// Adjust Prototype Token Settings Macro
// Author: PrototypeESBU
// v1.0
// Description: Adjusts the prototype token setting for all actors in the game. Update values belown before running.
// -------- display values chart --------------------------------
//  0 | Never Displayed
// 10 | When Controlled
// 20 | Hovered by Owner
// 30 | Hovered by Anyone
// 40 | Always for Owner
// 50 | Always for Everyone
// ----- Set these values accordingly---------------------------
const updateMonsters = true;
const Monster_displayNamesValue = 40;
const Monster_displayBarsValue = 40;
const Monster_bar1Value = "attributes.hp";

const updateCharacters = true;
const Character_displayNamesValue = 50;
const Character_displayBarsValue = 50;
const Character_bar1Value = "attributes.hp";
// --------------------------------------------------------------
// --------------------------------------------------------------

let npcsUpdated = 0;
let playersUpdated = 0;
for (const gameActor of game.actors) {

    if (gameActor.type === "NPC" && updateMonsters){
        gameActor.prototypeToken.update({
            displayName: Monster_displayNamesValue,
            displayBars: Monster_displayBarsValue,
            bar1: {
                attribute: Monster_bar1Value
            }
        })
        npcsUpdated++;
        continue;
    }
    if (gameActor.type === "Player" && updateCharacters){
        gameActor.prototypeToken.update({
            displayName: Character_displayNamesValue,
            displayBars: Character_displayBarsValue,
            bar1: {
                attribute: Character_bar1Value
            }
        })
        playersUpdated++;
        continue;
    }

}
ui.notifications.info(`${npcsUpdated} Monsters and ${playersUpdated} Players token updated.`);

