Apply Community Token Art.command:
// Apply Community Token Art
// Author: PrototypeESBU
// v1.0
// Requires: Shadowdark Community Tokens module installed.
// Description: Updates monsters in the current scene and actors tab that have the default "red cowl" and "eyes" monster token and portrait art with matching artwork from the Shadowdark Community Tokens project. 
// --------------------------------
const update_NPC_in_Scene = true;
const update_NPC_in_ActorsTab = true;
// --------------------------------

const defaults = [
    "systems/shadowdark/assets/tokens/cowled_token.webp",
    "modules/shadowdark-community-content/assets/tokens/default_monster.webp"
]

let tokensUpdated = 0;
let portraitsUpdated = 0;

if (!game.modules.get("shadowdark-community-tokens").active) {
    ui.notifications.error("ERROR: Install and activate the shadowdark-community-tokens module");
    return;
}
const monsters = await game.packs.get("shadowdark.monsters");

if (update_NPC_in_Scene) {
    for (const token of game.scenes.active.tokens) {
        const actor = game.actors.get(token.actorId);
        if (actor.type !== "NPC") continue;

        if (defaults.includes(token.texture.src)) {
            const art = await getMonsterArt(actor.name);
            if (art) {
                console.log(`Token: ${actor.name}\n Art:${art.token}`);
                await token.update({"texture.src": art.token});
                tokensUpdated++;
            }
        }
    }
}

if (update_NPC_in_ActorsTab) {
    for (const actor of game.actors) {
        if (actor.type !== "NPC") continue;

        if (defaults.includes(actor.prototypeToken.texture.src) || defaults.includes(actor.img)) {
            const art = await getMonsterArt(actor.name);
            if (art) {
                if (defaults.includes(actor.prototypeToken.texture.src)){
                    console.log(`Actor Tab Token: ${actor.name}\n Art:${art.token}`);
                    await actor.update({"prototypeToken.texture.src": art.token});
                    tokensUpdated++;
                }

                if (defaults.includes(actor.img))  {
                    console.log(`Portrait: ${actor.name}`);
                    await actor.update({"img": art.portrait});
                    portraitsUpdated++
                }
            }
        };
    }
}

async function getMonsterArt(name){
    const monster = monsters.index.find(x => x.name === name);
    if (monster) {
        const monsterObj = await fromUuid(monster.uuid);
        return {
            token: monsterObj.prototypeToken.texture.src,
            portrait: monsterObj.img
        }
    }
    return null;
}

ui.notifications.info(`${tokensUpdated} tokens and ${portraitsUpdated} portraits updated.`);

Crawling Helper.command:
// Crawling Helper
// Author: Evounamed (special thanks to Prototype for suggested improvements)
// v4.1

// SPECIAL ATTENTION: This macro will only show Rollable Tables that begin with
// "Random Encounters:" in the title. 

/**
 * Macro Purpose:
 * - Automates random encounter checks during dungeon exploration via round tracker.
 * - Integrates encounter frequency, distance and activity rolls per system provided roll tables.
 * - Note: This uses the Combat Tracker to track rounds and does NOT know the difference between crawling rounds and combat rounds. The user should IGNORE results during combat, there is no current way to differentiate between crawling/combat rounds in Foundry VTT.
 */

// Ensure a combat round tracker is active
if (!game.combat) {
    ui.notifications.warn("Combat round tracker not active!");
    return;
}

// Constants for danger levels
const DANGER_LEVELS = {
    Unsafe: 3,    // Check every 3 rounds
    Risky: 2,     // Check every 2 rounds
    Deadly: 1     // Check every round
};

// Ensure previous hook is removed
if (game.explorationHookId) {
    Hooks.off("updateCombat", game.explorationHookId);
}

/**
 * Fetch roll tables with "Random Encounters:" in their name from both the world and compendiums.
 */
const getRandomEncounterTables = async () => {
    const filterTables = (collection) => {
        return collection.filter(table => table.name.match(/Random\s+Encounters:/i))
                         .map(t => ({ name: t.name, id: t.uuid }));
    };

    const compendiumTables = [];
    for (let pack of game.packs) {
        if (pack.metadata.type === "RollTable") {
            const tables = await pack.getDocuments();
            compendiumTables.push(...filterTables(tables));
        }
    }

    const worldTables = filterTables(game.tables.contents);
    return [...compendiumTables, ...worldTables];
};

/**
 * Dialog for Dungeon Exploration Setup
 * Allows the user to configure the danger level and encounter table.
 */
(async () => {
    const allTables = await getRandomEncounterTables();

    new Dialog({
        title: "Crawling Helper",
        content: `
            <div style="font-family: Arial, sans-serif; font-size: 14px; padding: 10px;">
                <form>
                    <div class="form-group">
                        <label for="danger-level" style="color: #990000; font-weight: bold;">Select Danger Level:</label>
                        <select id="danger-level" style="width: 100%;">
                            ${Object.keys(DANGER_LEVELS).map(level => `<option value="${level}">${level}</option>`).join("")}
                        </select>
                    </div>
                    <div class="form-group">
                        <label for="roll-table" style="color: #990000; font-weight: bold;">Select Random Encounter Table:</label>
                        <select id="roll-table" style="width: 100%;">
                            ${allTables.map(table => `<option value="${table.id}">${table.name}</option>`).join("")}
                        </select>
                    </div>
                </form>
            </div>
        `,
        buttons: {
            start: {
                icon: '<i class="fas fa-play" style="color: #28a745;"></i>',
                label: "Start Exploration",
                callback: async (html) => {
                    const dangerLevel = html.find("#danger-level").val();
                    const rollTableId = html.find("#roll-table").val();

                    if (!rollTableId) {
                        ui.notifications.warn("Please select a random encounter table.");
                        return;
                    }

                    const roundsToCheck = DANGER_LEVELS[dangerLevel];

                    // Clear any existing flags
                    await game.combat.unsetFlag("world", "dungeonExploration");

                    // Initialize exploration tracking
                    await game.combat.setFlag("world", "dungeonExploration", {
                        roundsToCheck,
                        rollTableId
                    });

                    ui.notifications.info(`Exploration started with danger level: ${dangerLevel}`);
                }
            },
            cancel: {
                icon: '<i class="fas fa-times" style="color: #dc3545;"></i>',
                label: "Cancel",
                callback: () => console.log("Exploration setup cancelled.")
            }
        }
    }).render(true);
})();

/**
 * Helper Function: Create Chat Card
 * Generates a styled chat card for encounter results.
 */
const createChatCard = (round, resultText, distance, activity, treasure, reaction) => {
    ChatMessage.create({
        speaker: { alias: game.user.name },
        whisper: [game.user.id],
        content: `
            <div style="font-family: 'JSL Blackletter', Georgia, serif; color: #990000;">
                <h2 style="text-align: center;">Dungeon Encounter</h2>
            </div>
            <hr>
            <p>Round:<strong> ${round}</strong></p>
            <p>Result:<strong> ${resultText}</strong></p>
            <hr>
            <p>Starting Distance:<strong> ${distance}</strong></p>
            <p>Activity:<strong> ${activity}</strong></p>
            <p>Treasure:<strong> ${treasure}</strong></p>
            <p>Reaction (Unmodified):<strong> ${reaction}</strong></p>
        `
    });
};

/**
 * Helper Function: Retrieve Roll Table
 * Dynamically retrieves a roll table from the world or compendium.
 */
const retrieveRollTable = async (rollTableId) => {
    console.log("Attempting to fetch roll table:", rollTableId);
    try {
        if (rollTableId.startsWith("Compendium.")) {
            const table = await fromUuid(rollTableId);
            if (!table) throw new Error(`Compendium table with UUID ${rollTableId} not found.`);
            return table;
        } else if (rollTableId.startsWith("RollTable.")) {
            const worldTableId = rollTableId.replace("RollTable.", "");
            const worldTable = game.tables.get(worldTableId);
            if (!worldTable) throw new Error(`World table with ID ${worldTableId} not found.`);
            return worldTable;
        } else {
            throw new Error(`Invalid roll table ID format: ${rollTableId}`);
        }
    } catch (error) {
        console.error("Failed to retrieve roll table:", error);
        throw new Error("Roll table could not be resolved.");
    }
};

/**
 * Hook: Monitor Combat Round Changes
 * Automatically triggers random encounter checks based on configured danger level.
 */
const explorationHook = async (combat, updateData) => {
    if (!("round" in updateData)) return;

    const explorationData = combat.getFlag("world", "dungeonExploration");
    if (!explorationData) return;

    const { roundsToCheck, rollTableId } = explorationData;
    const currentRound = combat.round || 1;

    if (currentRound % roundsToCheck === 0) {
        try {
            const encounterCheck = new Roll("1d6");
            await encounterCheck.evaluate();

            if (encounterCheck.total === 1) {
                const rollTable = await retrieveRollTable(rollTableId);
                const roll = await rollTable.roll();
                const resultText = roll.results.map(result => result.text).join(", ");

                const pack = game.packs.get("shadowdark.rollable-tables");

                const distanceTableID = pack.index.find(o => o.name === "Random Encounter: Distance")._id;
                const distanceTable = await pack.getDocument(distanceTableID);
                const distanceResult = await distanceTable.roll();
                const distance = distanceResult.results[0].text;

                const activityTableID = pack.index.find(o => o.name === "Random Encounter: Activity")._id;
                const activityTable = await pack.getDocument(activityTableID);
                const activityResult = await activityTable.roll();
                const activity = activityResult.results[0].text;

                const treasureRoll = new Roll("1d100");
                await treasureRoll.evaluate();
                const treasure = treasureRoll.total >= 50 ? "have treasure" : "have no treasure";

                const reactionTableID = pack.index.find(o => o.name === "Random Encounter: Reaction")._id;
                const reactionTable = await pack.getDocument(reactionTableID);
                const reactionResult = await reactionTable.roll();
                const reaction = reactionResult.results[0].text;

                createChatCard(currentRound, resultText, distance, activity, treasure, reaction);
            } else {
                ChatMessage.create({
                    speaker: { alias: game.user.name },
                    whisper: [game.user.id],
                    content: `
                        <div style="font-family: 'JSL Blackletter', Georgia, serif; color: #990000;">
                            <h2 style="text-align: center;">Random Encounter Check</h2>
                        </div>
                        <hr>
                        <p><strong>Round:</strong> ${currentRound}</p>
                        <p>No encounter occurred (Rolled ${encounterCheck.total}).</p>
                    `
                });
            }
        } catch (error) {
            console.error("Error during encounter check or roll: ", error);
            ui.notifications.error("An error occurred during the encounter check. Check the console for details.");
        }
    }
};

// Assign and activate the hook
game.explorationHookId = Hooks.on("updateCombat", explorationHook);

