Toggle Chaos Mode.command:
// Toggle Chaos Mode
// Author: PrototypeESBU
// v1.2
// Description: Enables Chaos Mode where initiative is re-rolled every round.
// -----------------------------------------------------
const displayChatMessage = true;
// -----------------------------------------------------
//------------------------------------------------------

// Find existing chaos mode hooks
let hookId = 0;
if (Hooks.events.combatRound) {
    for (const event of Hooks.events.combatRound) {
        if (event.fn.name === "chaosMode") hookId = event.id;
    }
}

if (hookId){
    // Disable chaos mode
    Hooks.off('combatRound', hookId);
    ui.notifications.error("Chaos Mode Disabled");
}
else {
    // Enabled chaos mode
    Hooks.on('combatRound', chaosMode);
    ui.notifications.info("Chaos Mode Enabled");
}

async function chaosMode(){
    //reset initiative
    await game.combat.resetAll();

    // Iterate over Combatants, performing an initiative roll for each
    const updates = [];
    const combatants = [];
    for ( const combatant of game.combat.combatants ) {
        if ( !combatant?.isOwner ) continue;
        // Produce an initiative roll for the Combatant
        const roll = combatant.getInitiativeRoll();
        await roll.evaluate();
        updates.push({_id: combatant.id, initiative: roll.total});
        combatants.push({name:combatant.name, initiative: roll.total})
    }
    if ( !updates.length ) return;

    // Update multiple combatants
    await game.combat.updateEmbeddedDocuments("Combatant", updates);

    //set new starting player
    await game.combat.update({turn: 0});

    // Craft a chat message
    if (displayChatMessage) {
        let message = `<h3 class="larger">Initiative Rolls</h3>`;
        for ( const combatant of combatants.sort((a,b) => b.initiative - a.initiative)) {
            message = message.concat(`<div class="flexrow"><span>${combatant.name}</span><span>${combatant.initiative}</span></div>`);
        }
        ChatMessage.create({flavor: `Chaos Mode (Round ${game.combat.round})`, content: `<div class="shadowdark">${message}</div>`});
    }
}

